// Generated from the tested framework sources. Each template is embedded byte for byte.
// Do not edit by hand: change the Bash source, re-run the framework tests, and regenerate this file.

enum FrameworkTemplates {
    /// Framework files that are copied unchanged, keyed by their path inside framework/.
    static let staticFiles: [(path: String, contents: String, isExecutable: Bool)] = [
        ("enrollment.sh", enrollmentScript, true),
        ("uninstall.sh", uninstallScript, true),
        ("lib/common.sh", libraryCommon, false),
        ("lib/logging.sh", libraryLogging, false),
        ("lib/state.sh", libraryState, false),
        ("lib/user.sh", libraryUser, false),
        ("lib/network.sh", libraryNetwork, false),
        ("lib/dialog.sh", libraryDialog, false),
        ("lib/validation.sh", libraryValidation, false),
        ("lib/task-runner.sh", libraryTaskRunner, false),
    ]

    static let enrollmentScript = #"""
#!/bin/bash
#
# enrollment.sh - swiftDialog enrollment experience for Microsoft Intune.
# Generated by Enrollment Bundle Studio. Regenerate from the project instead of editing this file.
#
# Script type : Plain shell script. Runs as root from the LaunchDaemon installed by the package;
#               can also be run by Intune or with sudo for testing.
# Run context : root (device). User-context tasks run with launchctl asuser.
# No console user: the dialog is skipped and non-disruptive tasks continue. Tasks that need the user
#               are deferred; the run ends with DEFERRED (exit 1) and resumes on the next run.
# swiftDialog : must be at least dialog_min_version (config/enrollment.conf). If missing or too old
#               the dialog is skipped, the problem is logged, and tasks continue.
# Logs        : /Library/Logs/Microsoft/IntuneScripts/onBoarding/, one per run, newest 10 kept,
#               mode 644 so the user can read them.
#
# Usage:
#   enrollment.sh             Normal production run. This is how launchd and Intune run it.
#   enrollment.sh --dry-run   Check preconditions and log what would happen. Changes nothing, shows no dialog.
#   enrollment.sh --preview   Show the real dialog to the console user with simulated progress. Changes nothing else.
#   enrollment.sh --force     Re-evaluate every task, including tasks that already completed.
#   enrollment.sh --help      Show this help.
#   When --dry-run and --preview are both given, --dry-run wins.
#   Manual testing: sudo "/Library/Application Support/<Organization>/Enrollment/enrollment.sh" --dry-run
#
# Onboarding flag: onboarding_flag (config) is written after success or success with warnings. When it
#               already exists the run is skipped (unless --force): no dialog, tasks, wallpaper or Dock changes.
#               The package itself still installs its files on such a Mac; only this script honours the flag.
#
# Exit codes: 0 = success or nothing to do; 1 = failure, interrupted or deferred (runs again later).

set -u
umask 022

script_dir="$(cd "$(dirname "$0")" 2>/dev/null && pwd -P)"
if [ -z "$script_dir" ] || [ ! -f "$script_dir/config/enrollment.conf" ]; then
    printf 'enrollment.sh: cannot find config/enrollment.conf next to the script.\n' >&2
    printf 'FAILED: enrollment bundle incomplete\n'
    exit 1
fi

# shellcheck source=/dev/null
. "$script_dir/config/enrollment.conf"
for library in common logging state user network dialog validation task-runner; do
    # shellcheck source=/dev/null
    . "$script_dir/lib/$library.sh"
done

dry_run=0
preview_mode=0
force=0
interrupted=0

print_usage() {
    sed -n '/^# Usage:/,/^# Exit codes/p' "$0" | sed 's/^# \{0,1\}//'
}

cleanup() {
    stop_running_tasks
    remove_temp_files
    lock_release
}

on_signal() {
    if is_true "$interrupted"; then
        return
    fi
    interrupted=1
    log_warn "Received $1; stopping. Completed tasks are kept and the run resumes next time."
    stop_running_tasks
    dialog_quit
    intune_result "FAILED" "Interrupted by $1; will resume" "bundle=$bundle_version"
    exit 1
}

trap cleanup EXIT
trap 'on_signal TERM' TERM
trap 'on_signal INT' INT
trap 'on_signal HUP' HUP

# verify_bundle - the installed files this run depends on.
verify_bundle() {
    local missing=0 library
    for library in common logging state user network dialog validation task-runner; do
        if [ ! -f "$script_dir/lib/$library.sh" ]; then
            log_error "Missing library lib/$library.sh"
            missing=1
        fi
    done
    if [ ! -f "$script_dir/config/dialog.json" ]; then
        log_error "Missing config/dialog.json"
        missing=1
    fi
    if [ "$(count_lines "$(task_files)")" -eq 0 ]; then
        log_error "No task files in $script_dir/tasks"
        missing=1
    fi
    if [ "$script_dir" != "$install_dir" ]; then
        log_warn "Running from $script_dir, but the project's install location is $install_dir. The dialog uses the files here; the LaunchDaemon and uninstall.sh use $install_dir."
    fi
    [ "$missing" -eq 0 ]
}

# retire_launch_daemon - after success the daemon is no longer needed at boot.
retire_launch_daemon() {
    local plist="/Library/LaunchDaemons/$launchd_label.plist"
    if [ -f "$plist" ]; then
        if rm -f "$plist"; then
            log "Removed $plist so enrollment does not run again at startup."
        else
            log_warn "Could not remove $plist."
        fi
    fi
}

# enrollment_window_ok - succeeds when this Mac's MDM enrollment is recent enough to be a fresh enrollment.
# Fails (and sets enrollment_window_reason) when the MDM profile or its date is missing or unreadable, or when the
# enrollment is older than enrollment_window_hours. Always succeeds when the onboarding guard is off.
enrollment_window_reason=""
enrollment_window_ok() {
    local raw date_value seconds age
    enrollment_window_reason=""
    [ -n "${onboarding_flag:-}" ] || return 0
    [ "${enrollment_window_hours:-0}" -gt 0 ] 2>/dev/null || return 0
    raw="$(profiles -P -v 2>/dev/null | grep -B 5 "profileIdentifier: Microsoft.Profiles.MDM" | grep "installationDate" | head -n 1 | sed 's/.*installationDate:[[:space:]]*//')"
    if [ -z "$raw" ]; then
        enrollment_window_reason="no MDM enrollment date found"
        log_warn "MDM profile (Microsoft.Profiles.MDM) not found or has no installationDate; this Mac may not be MDM enrolled."
        return 1
    fi
    date_value="$raw"
    if printf '%s' "$raw" | grep -Eq '^[0-9]{4}-[0-9]{2}-[0-9]{2}[[:space:]][0-9]{2}:[0-9]{2}:[0-9]{2}$'; then
        date_value="$raw +0000"
        log "MDM install date has no timezone; assuming UTC."
    fi
    seconds="$(date -j -f "%Y-%m-%d %H:%M:%S %z" "$date_value" "+%s" 2>/dev/null)"
    if [ -z "$seconds" ]; then
        enrollment_window_reason="MDM enrollment date could not be read"
        log_warn "Could not parse the MDM install date [$date_value]."
        return 1
    fi
    age=$(( ($(now_epoch) - seconds) / 3600 ))
    log "MDM enrollment date [$date_value], $age hour(s) ago (window ${enrollment_window_hours}h)."
    if [ "$age" -gt "$enrollment_window_hours" ]; then
        enrollment_window_reason="enrolled $age hour(s) ago, more than the ${enrollment_window_hours}h window"
        return 1
    fi
    return 0
}

# first_run_pending - true until a run has started on this Mac (the window only gates the first run, so a run
# that resumes after a restart is never blocked by it).
first_run_pending() {
    [ -z "$(state_read last.run)" ]
}

# onboarding_flag_present - the flag that marks a Mac as onboarded.
onboarding_flag_present() {
    [ -n "${onboarding_flag:-}" ] && [ -f "$onboarding_flag" ]
}

# write_onboarding_flag OUTCOME - written after a successful enrollment so the package is not installed again.
write_onboarding_flag() {
    local directory
    if [ -z "${onboarding_flag:-}" ]; then
        return 0
    fi
    directory="$(dirname "$onboarding_flag")"
    if ! mkdir -p "$directory"; then
        log_error "Cannot create $directory for the onboarding flag."
        return 1
    fi
    chown root:wheel "$directory" 2>/dev/null
    chmod 755 "$directory"
    if printf 'onboarded=%s\nproject=%s\nbundle=%s\noutcome=%s\n' "$(date '+%Y-%m-%dT%H:%M:%S%z')" "$project_id" "$bundle_version" "$1" > "$onboarding_flag"; then
        chown root:wheel "$onboarding_flag" 2>/dev/null
        chmod 644 "$onboarding_flag"
        log "Wrote onboarding flag $onboarding_flag."
        return 0
    fi
    log_error "Could not write the onboarding flag $onboarding_flag."
    return 1
}

# dry_run_report - logs what each task would do, using read-only checks only.
dry_run_report() {
    local file present
    while IFS= read -r file; do
        [ -n "$file" ] || continue
        task_load "$file" || continue
        present="not checked"
        case "$TASK_TYPE" in
            applicationDetection | packageInstallation)
                if detect_application; then present="detected"; else present="not detected"; fi
                ;;
        esac
        log "DRY-RUN: task $TASK_ID ($TASK_TYPE${TASK_STRATEGY:+, $TASK_STRATEGY}) required=$TASK_REQUIRED context=$TASK_CONTEXT timeout=${TASK_TIMEOUT}s batch=$TASK_BATCH depends='$TASK_DEPENDS' current=$present stored=$(state_get_task "$TASK_ID")"
    done <<< "$(task_files)"
}

# run_preview - shows the real dialog with simulated statuses. No detection, no installs, no state.
run_preview() {
    local file step=0
    if ! wait_for_console_user 5 || ! dialog_prepare; then
        intune_result "PREVIEW" "Dialog not shown: no console user or swiftDialog unavailable"
        return 0
    fi
    dialog_collect_values
    dialog_start || { intune_result "FAILED" "Could not start swiftDialog"; return 1; }
    total_tasks="$(count_lines "$(task_files)")"
    while IFS= read -r file; do
        [ -n "$file" ] || continue
        task_load "$file" || continue
        step=$((step + 1))
        if [ "$TASK_LIST_INDEX" -ge 0 ] 2>/dev/null && ! is_true "$TASK_LIST_SUMMARY"; then
            dialog_set_item "$TASK_LIST_INDEX" running "$(task_text running)"
            sleep 1
            dialog_set_item "$TASK_LIST_INDEX" complete "$(task_text complete)"
        elif is_true "$TASK_LIST_SUMMARY"; then
            dialog_set_item "$TASK_LIST_INDEX" complete "Complete"
        fi
        dialog_progress "$step" "$step of $total_tasks complete"
    done <<< "$(task_files)"
    dialog_finish success
    dialog_wait_for_exit 120
    intune_result "PREVIEW" "Dialog shown with simulated progress" "tasks=$total_tasks"
    return 0
}

main() {
    local outcome
    if ! log_setup; then
        intune_result "FAILED" "Cannot write logs to $logandmetadir"
        return 1
    fi
    log "===== $appname: $project_name, bundle $bundle_version (project $project_id) ====="
    if is_true "$dry_run"; then
        log "DRY-RUN: preconditions are checked and planned actions logged. Nothing is changed and no dialog is shown."
    elif is_true "$preview_mode"; then
        log "PREVIEW: the real dialog is shown with simulated progress. Nothing else is changed."
    fi
    if ! verify_bundle; then
        intune_result "FAILED" "Enrollment bundle is incomplete" "bundle=$bundle_version"
        return 1
    fi

    if is_true "$dry_run"; then
        if detect_console_user; then
            log "DRY-RUN: console user is $console_user."
        else
            log "DRY-RUN: no console user; the dialog would be skipped."
        fi
        if [ -x "$dialog_path" ]; then
            log "DRY-RUN: swiftDialog found at $dialog_path ($("$dialog_path" --version 2>/dev/null | head -n 1))."
        else
            log "DRY-RUN: swiftDialog not found at $dialog_path; a normal run installs it automatically from the official GitHub release."
        fi
        if onboarding_flag_present; then
            log "DRY-RUN: onboarding flag present at $onboarding_flag; a normal run would skip (use --force to run anyway)."
        elif [ -n "${onboarding_flag:-}" ]; then
            log "DRY-RUN: no onboarding flag at $onboarding_flag; it would be written after a successful run."
        fi
        if ! onboarding_flag_present && first_run_pending; then
            if enrollment_window_ok; then
                log "DRY-RUN: the enrollment window check passes."
            else
                log "DRY-RUN: a normal run would skip: $enrollment_window_reason (use --force to run anyway)."
            fi
        fi
        if [ -n "${wallpaper_source:-}" ]; then
            if [ "$(state_read wallpaper.applied)" = "$(wallpaper_fingerprint "$script_dir/$wallpaper_source")" ]; then
                log "DRY-RUN: the wallpaper was already applied; it would be left alone."
            else
                log "DRY-RUN: the wallpaper would be copied to $wallpaper_target and applied for the console user."
            fi
        fi
        if [ "${dock_enabled:-0}" = "1" ]; then
            if [ -n "${dock_fingerprint:-}" ] && [ "$(state_read dock.applied)" = "$dock_fingerprint" ]; then
                log "DRY-RUN: the Dock was already configured; it would be left alone."
            else
                log "DRY-RUN: after a successful enrollment the Dock would be set up with ${dock_item_count:-0} app(s); apps that are not installed are skipped."
            fi
        fi
        dry_run_report
        intune_result "DRY-RUN" "Checked $(count_lines "$(task_files)") task(s); nothing changed" "bundle=$bundle_version"
        return 0
    fi

    if is_true "$preview_mode"; then
        run_preview
        return $?
    fi

    if onboarding_flag_present; then
        if is_true "$force"; then
            log "Onboarding flag present at $onboarding_flag, but --force was given; running anyway."
        else
            log "Onboarding flag present at $onboarding_flag: this Mac is already onboarded."
            retire_launch_daemon
            intune_result "SKIPPED" "Already onboarded (flag present)" "bundle=$bundle_version"
            return 0
        fi
    fi

    if first_run_pending && ! enrollment_window_ok; then
        if is_true "$force"; then
            log "Not a fresh enrollment ($enrollment_window_reason), but --force was given; running anyway."
        else
            log "Not a fresh enrollment ($enrollment_window_reason): skipping."
            retire_launch_daemon
            intune_result "SKIPPED" "Not a fresh enrollment: $enrollment_window_reason" "bundle=$bundle_version"
            return 0
        fi
    fi

    # The run lock lives in the state directory, so create that first.
    if ! state_init; then
        intune_result "FAILED" "Cannot create state directory" "bundle=$bundle_version"
        return 1
    fi
    if ! lock_acquire; then
        intune_result "SKIPPED" "Another enrollment run is active"
        return 0
    fi
    state_reconcile "$force"
    if [ "$(state_read completion)" = "success" ] && ! is_true "$force"; then
        intune_result "SKIPPED" "Enrollment already complete" "bundle=$bundle_version"
        return 0
    fi

    wait_for_network 300
    dialog_ensure_installed || true
    wait_for_console_user "${user_wait_timeout:-3600}"
    if dialog_prepare; then
        dialog_collect_values
        dialog_start || log_error "Could not start swiftDialog; continuing without a dialog."
    else
        dialog_collect_values
    fi

    apply_wallpaper || true
    run_all_tasks
    outcome="$(evaluate_outcome)"
    log "Outcome: $outcome"
    state_write completion "$outcome"
    case "$outcome" in
        success|warnings) apply_dock || true ;;
    esac
    dialog_finish "$outcome"
    dialog_wait_for_exit 3600
    dialog_run_completion_command "$outcome"

    case "$outcome" in
        success)
            write_onboarding_flag "$outcome"
            retire_launch_daemon
            intune_result "SUCCESS" "Enrollment complete" "bundle=$bundle_version" "tasks=$total_tasks"
            return 0
            ;;
        warnings)
            write_onboarding_flag "$outcome"
            retire_launch_daemon
            intune_result "SUCCESS" "Enrollment complete with warnings" "bundle=$bundle_version" "tasks=$total_tasks"
            return 0
            ;;
        deferred)
            intune_result "DEFERRED" "Waiting for a logged-in user or pending tasks" "bundle=$bundle_version"
            return 1
            ;;
        *)
            intune_result "FAILED" "Required enrollment tasks did not complete" "bundle=$bundle_version"
            return 1
            ;;
    esac
}

unknown_argument=""
while [ "$#" -gt 0 ]; do
    case "$1" in
        --dry-run) dry_run=1 ;;
        --preview) preview_mode=1 ;;
        --force) force=1 ;;
        --help | -h) print_usage; exit 0 ;;
        *) unknown_argument="$1"; break ;;
    esac
    shift
done
if is_true "$dry_run"; then
    preview_mode=0
fi

if [ "$(id -u)" -ne 0 ]; then
    log_error "This script must run as root."
    intune_result "FAILED" "Not running as root"
    exit 1
fi
if [ -n "$unknown_argument" ]; then
    log_setup
    log_error "Unknown argument: $unknown_argument (see --help)"
    intune_result "FAILED" "Unknown argument $unknown_argument"
    exit 1
fi

main
exit $?
"""#

    static let uninstallScript = #"""
#!/bin/bash
#
# uninstall.sh - removes the enrollment framework, its LaunchDaemon and its state. Logs are kept.
# Generated by Enrollment Bundle Studio.
#
# Script type : Plain shell script. Run as root via Intune or sudo.
# Usage:
#   uninstall.sh            Remove the LaunchDaemon, the state directory and the installed framework.
#   uninstall.sh --dry-run  Log what would be removed. Changes nothing.
#   uninstall.sh --help     Show this help.
# Exit codes: 0 = removed or nothing to remove; 1 = failure.

set -u
umask 022

script_dir="$(cd "$(dirname "$0")" 2>/dev/null && pwd -P)"
if [ -z "$script_dir" ] || [ ! -f "$script_dir/config/enrollment.conf" ]; then
    printf 'uninstall.sh: cannot find config/enrollment.conf next to the script.\n' >&2
    printf 'FAILED: enrollment bundle incomplete\n'
    exit 1
fi
# shellcheck source=/dev/null
. "$script_dir/config/enrollment.conf"
# shellcheck source=/dev/null
. "$script_dir/lib/common.sh"
# shellcheck source=/dev/null
. "$script_dir/lib/logging.sh"

dry_run=0
while [ "$#" -gt 0 ]; do
    case "$1" in
        --dry-run) dry_run=1 ;;
        --help | -h) sed -n '/^# Usage:/,/^# Exit codes/p' "$0" | sed 's/^# \{0,1\}//'; exit 0 ;;
        *)
            if [ "$(id -u)" -eq 0 ]; then log_setup; fi
            log_error "Unknown argument: $1"
            intune_result "FAILED" "Unknown argument $1"
            exit 1
            ;;
    esac
    shift
done

if [ "$(id -u)" -ne 0 ]; then
    log_error "This script must run as root."
    intune_result "FAILED" "Not running as root"
    exit 1
fi
if ! log_setup; then
    intune_result "FAILED" "Cannot write logs"
    exit 1
fi
if is_true "$dry_run"; then
    log "DRY-RUN: logging what would be removed; nothing is changed."
fi
log "Uninstalling $project_name (bundle $bundle_version)."

failures=0
plist="/Library/LaunchDaemons/$launchd_label.plist"
if launchctl print "system/$launchd_label" >/dev/null 2>&1; then
    if is_true "$dry_run"; then
        log "DRY-RUN: would stop LaunchDaemon $launchd_label"
    elif launchctl bootout "system/$launchd_label" >> "$logfile" 2>&1; then
        log "Stopped LaunchDaemon $launchd_label"
    else
        log_warn "Could not stop LaunchDaemon $launchd_label"
    fi
fi
if [ -f "$plist" ]; then
    if is_true "$dry_run"; then
        log "DRY-RUN: would remove $plist"
    elif rm -f "$plist"; then
        log "Removed $plist"
    else
        log_error "Could not remove $plist"
        failures=$((failures + 1))
    fi
fi
if [ -n "${onboarding_flag:-}" ] && [ -f "$onboarding_flag" ]; then
    log "Keeping the onboarding flag $onboarding_flag so this Mac is not onboarded again. Remove it by hand to allow re-onboarding."
fi
safe_remove_dir "$state_dir" || failures=$((failures + 1))
# The detection placeholder app. One inside the install directory goes with it; one elsewhere is removed here,
# and only when the path is an absolute .app path without "..".
case "${detection_app:-}" in
    "$install_dir"/*) ;;
    /*.app)
        case "$detection_app" in
            *..*) log_warn "Not removing the detection app, its path contains '..': $detection_app" ;;
            *)
                if [ -d "$detection_app" ]; then
                    if is_true "$dry_run"; then
                        log "DRY-RUN: would remove $detection_app"
                    elif rm -rf "$detection_app"; then
                        log "Removed $detection_app"
                    else
                        log_error "Could not remove $detection_app"
                        failures=$((failures + 1))
                    fi
                fi
                ;;
        esac
        ;;
esac
safe_remove_dir "$install_dir" || failures=$((failures + 1))

if [ "$failures" -gt 0 ]; then
    intune_result "FAILED" "Uninstall finished with $failures error(s)"
    exit 1
fi
if is_true "$dry_run"; then
    intune_result "DRY-RUN" "Nothing removed" "bundle=$bundle_version"
else
    intune_result "SUCCESS" "Enrollment framework removed" "bundle=$bundle_version"
fi
exit 0
"""#

    static let libraryCommon = #"""
# shellcheck shell=bash
# common.sh - shared helpers for the enrollment framework.
# Generated by Enrollment Bundle Studio. Sourced by enrollment.sh. Bash 3.2 compatible.

PATH="/usr/bin:/bin:/usr/sbin:/sbin:/usr/local/bin"
export PATH

newline='
'

temp_files=""

# register_temp PATH - remembered and removed by cleanup on exit.
register_temp() {
    temp_files="$temp_files$1$newline"
}

remove_temp_files() {
    local file
    while IFS= read -r file; do
        if [ -n "$file" ] && [ -e "$file" ]; then
            rm -f "$file"
        fi
    done <<< "$temp_files"
    temp_files=""
}

# is_true VALUE - true for 1
is_true() {
    [ "${1:-0}" = "1" ]
}

now_epoch() {
    date +%s
}

# replace_all TEXT SEARCH REPLACEMENT - literal replacement without pattern or & surprises.
replace_all() {
    local text="$1" search="$2" replacement="$3" result=""
    if [ -z "$search" ]; then
        printf '%s' "$text"
        return 0
    fi
    while [ "${text#*"$search"}" != "$text" ]; do
        result="$result${text%%"$search"*}$replacement"
        text="${text#*"$search"}"
    done
    printf '%s' "$result$text"
}

# json_escape TEXT - escape for use inside a JSON string.
json_escape() {
    local s="$1"
    s="$(replace_all "$s" '\' '\\')"
    s="$(replace_all "$s" '"' '\"')"
    s="$(replace_all "$s" "$newline" '\n')"
    s="$(replace_all "$s" "$(printf '\r')" '\r')"
    s="$(replace_all "$s" "$(printf '\t')" '\t')"
    printf '%s' "$s"
}

# one_line TEXT - collapse newlines and commas for swiftDialog command-file values.
one_line() {
    local s="$1"
    s="$(replace_all "$s" "$newline" ' ')"
    s="$(replace_all "$s" ',' ' ')"
    printf '%s' "$s"
}

# version_ge A B - true when dotted version A >= B.
version_ge() {
    local i ai bi
    local -a av bv
    IFS=. read -r -a av <<< "$1"
    IFS=. read -r -a bv <<< "$2"
    for i in 0 1 2 3; do
        ai="${av[$i]:-0}"
        bi="${bv[$i]:-0}"
        ai="${ai%%[!0-9]*}"
        bi="${bi%%[!0-9]*}"
        ai="${ai:-0}"
        bi="${bi:-0}"
        if [ "$ai" -gt "$bi" ]; then
            return 0
        fi
        if [ "$ai" -lt "$bi" ]; then
            return 1
        fi
    done
    return 0
}

# code_in_list CODE "0 2 3" - true when CODE is in the space-separated list.
code_in_list() {
    local code="$1" item
    for item in $2; do
        if [ "$item" = "$code" ]; then
            return 0
        fi
    done
    return 1
}

# file_owner_mode PATH - prints "owner octalmode". GNU stat is tried first because BSD stat rejects -c
# without output, while GNU stat given BSD arguments prints file system details before failing.
file_owner_mode() {
    stat -c '%U %a' "$1" 2>/dev/null || stat -f '%Su %Lp' "$1" 2>/dev/null
}

# file_is_root_protected PATH - owned by root and not writable by group or others.
file_is_root_protected() {
    local info owner mode
    info="$(file_owner_mode "$1")" || return 1
    owner="${info%% *}"
    mode="${info##* }"
    [ "$owner" = "root" ] || return 1
    case "$mode" in
        *[2367][0-7] | *[0-7][2367]) return 1 ;;
    esac
    return 0
}

# unsafe_directory_reason PATH - succeeds and prints a reason when PATH must never be changed recursively
# (relative, contains .., a system folder, or too shallow).
unsafe_directory_reason() {
    local target="$1" depth
    case "$target" in
        /*) ;;
        *) printf 'relative path'; return 0 ;;
    esac
    case "$target" in
        *..*) printf "path containing '..'"; return 0 ;;
    esac
    case "$target" in
        / | /Library | /Library/ | /Applications | /Users | /System | /usr | /bin | /sbin | /private | /var | \
        "/Library/Application Support" | "/Library/Application Support/" | /Library/LaunchDaemons)
            printf 'protected path'
            return 0
            ;;
    esac
    depth="$(printf '%s' "$target" | awk -F/ '{print NF-1}')"
    if [ "$depth" -lt 3 ]; then
        printf 'shallow path'
        return 0
    fi
    return 1
