    printf '%s\n' "$line" 2>/dev/null >> "$logfile"
    if [ -t 2 ]; then
        printf '%s\n' "$line" >&2
    fi
}

log() {
    _log_line "INFO" "$*"
}

log_warn() {
    _log_line "WARN" "$*"
}

log_debug() {
    if is_true "${debug_logging:-0}"; then
        _log_line "DEBUG" "$*"
    fi
    return 0
}

# log_error - logs at ERROR and, when stderr is not a terminal (Intune, launchd), writes one line to stderr.
log_error() {
    _log_line "ERROR" "$*"
    if [ ! -t 2 ]; then
        printf '%s: %s\n' "$appname" "$*" >&2
    fi
}

# log_setup - creates the log directory and this run's log with explicit ownership and permissions.
# Logs are 644 so the console user can read them.
log_setup() {
    if ! mkdir -p "$logandmetadir"; then
        printf '%s: cannot create %s\n' "$appname" "$logandmetadir" >&2
        return 1
    fi
    chown root:wheel "$logandmetadir" 2>/dev/null
    chmod 755 "$logandmetadir"
    # Every run gets its own log, even when two runs start within the same second.
    if [ -e "$logfile" ]; then
        logfile="${logfile%.log}-$$.log"
    fi
    if ! : > "$logfile"; then
        printf '%s: cannot create %s\n' "$appname" "$logfile" >&2
        return 1
    fi
    chown root:wheel "$logfile" 2>/dev/null
    chmod 644 "$logfile"
    rotate_logs
    return 0
}

# rotate_logs - keeps the newest $log_keep run logs. Timestamped names sort chronologically.
rotate_logs() {
    local count=0 file
    find "$logandmetadir" -maxdepth 1 -type f -name "${appname}_*.log" 2>/dev/null | sort -r | while IFS= read -r file; do
        count=$((count + 1))
        if [ "$count" -gt "$log_keep" ]; then
            rm -f "$file"
        fi
    done
}

# intune_result STATUS MESSAGE [key=value ...] - the one stdout line Intune records. Max 200 characters.
intune_result() {
    local status="$1" message="$2" line pair
    shift 2
    line="$status: $message"
    for pair in "$@"; do
        line="$line | $pair"
    done
    line="${line:0:200}"
    log "Intune result: $line"
    printf '%s\n' "$line"
}
"""#

    static let libraryState = #"""
# shellcheck shell=bash
# state.sh - protected task state, run lock and resume support.
# Generated by Enrollment Bundle Studio. Sourced by enrollment.sh. Bash 3.2 compatible.

lock_dir=""

state_task_file() {
    printf '%s/tasks/%s.status' "$state_dir" "$1"
}

# state_init - creates the state directory, root-only.
state_init() {
    local reason
    if reason="$(unsafe_directory_reason "$state_dir")"; then
        log_error "Refusing to use $reason as the state directory: $state_dir"
        return 1
    fi
    if ! mkdir -p "$state_dir/tasks"; then
        log_error "Cannot create state directory $state_dir"
        return 1
    fi
    chown -R root:wheel "$state_dir" 2>/dev/null
    chmod 700 "$state_dir"
    chmod 700 "$state_dir/tasks"
    return 0
}

# state_write NAME VALUE - atomic write of one state value.
state_write() {
    local target="$state_dir/$1" temporary
    temporary="$(mktemp "$state_dir/.write.XXXXXX")" || return 1
    printf '%s\n' "$2" > "$temporary"
    chmod 600 "$temporary"
    mv -f "$temporary" "$target"
}

state_read() {
    local value=""
    if [ -f "$state_dir/$1" ]; then
        IFS= read -r value < "$state_dir/$1"
    fi
    printf '%s' "$value"
}

# state_get_task ID - prints the stored status, or pending.
state_get_task() {
    local file value=""
    file="$(state_task_file "$1")"
    if [ -f "$file" ]; then
        IFS= read -r value < "$file"
    fi
    printf '%s' "${value:-pending}"
}

state_get_task_message() {
    local file="$state_dir/tasks/$1.message" value=""
    if [ -f "$file" ]; then
        IFS= read -r value < "$file"
    fi
    printf '%s' "$value"
}

# state_set_task ID STATUS [MESSAGE]
state_set_task() {
    local id="$1" status="$2" message="${3:-}"
    if is_true "${dry_run:-0}" || is_true "${preview_mode:-0}"; then
        return 0
    fi
    state_write "tasks/$id.status" "$status"
    state_write "tasks/$id.message" "$message"
    log "Task $id -> $status${message:+ ($message)}"
}

state_is_acceptable() {
    case "$1" in
        complete | completeWithWarnings) return 0 ;;
    esac
    return 1
}

state_is_terminal() {
    case "$1" in
        complete | completeWithWarnings | skipped | failed | timedOut) return 0 ;;
    esac
    return 1
}

# state_reconcile FORCE - clears task states when the project, the bundle version or --force require it.
state_reconcile() {
    local force="$1" stored_project stored_version
    stored_project="$(state_read project.id)"
    stored_version="$(state_read bundle.version)"
    if is_true "$force"; then
        log "--force given: re-evaluating every task."
        rm -f "$state_dir"/tasks/*.status "$state_dir"/tasks/*.message 2>/dev/null
        rm -f "$state_dir/completion" 2>/dev/null
    elif [ -n "$stored_project" ] && [ "$stored_project" != "$project_id" ]; then
        log "State belongs to project $stored_project; starting fresh for $project_id."
        rm -f "$state_dir"/tasks/*.status "$state_dir"/tasks/*.message "$state_dir/completion" 2>/dev/null
    elif [ -n "$stored_version" ] && [ "$stored_version" != "$bundle_version" ]; then
        log "Bundle version changed from $stored_version to $bundle_version: re-evaluating every task."
        rm -f "$state_dir"/tasks/*.status "$state_dir"/tasks/*.message "$state_dir/completion" 2>/dev/null
    fi
    state_write project.id "$project_id"
    state_write bundle.version "$bundle_version"
    state_write last.run "$(date '+%Y-%m-%dT%H:%M:%S%z')"
}

# lock_acquire - prevents duplicate runs; removes a lock whose process is gone.
lock_acquire() {
    local holder
    lock_dir="$state_dir/run.lock"
    if mkdir "$lock_dir" 2>/dev/null; then
        printf '%s\n' "$$" > "$lock_dir/pid"
        state_write current.pid "$$"
        log "Acquired run lock."
        return 0
    fi
    holder=""
    if [ -f "$lock_dir/pid" ]; then
        IFS= read -r holder < "$lock_dir/pid"
    fi
    if [ -n "$holder" ] && kill -0 "$holder" 2>/dev/null && ps -p "$holder" -o command= 2>/dev/null | grep -q "enrollment.sh"; then
        log "Another enrollment run is active (PID $holder)."
        lock_dir=""
        return 1
    fi
    log_warn "Removing stale run lock left by PID ${holder:-unknown}."
    rm -rf "$lock_dir"
    if mkdir "$lock_dir" 2>/dev/null; then
        printf '%s\n' "$$" > "$lock_dir/pid"
        state_write current.pid "$$"
        return 0
    fi
    log_error "Could not acquire the run lock."
    lock_dir=""
    return 1
}

lock_release() {
    if [ -n "$lock_dir" ] && [ -d "$lock_dir" ]; then
        rm -rf "$lock_dir"
        rm -f "$state_dir/current.pid" 2>/dev/null
        log "Released run lock."
    fi
    lock_dir=""
}
"""#

    static let libraryUser = #"""
# shellcheck shell=bash
# user.sh - console user detection and user-context execution.
# Generated by Enrollment Bundle Studio. Sourced by enrollment.sh. Bash 3.2 compatible.

console_user=""
console_uid=""

# detect_console_user - sets console_user and console_uid; empty, root and loginwindow mean no user.
detect_console_user() {
    local user uid
    user="$(scutil <<< "show State:/Users/ConsoleUser" 2>/dev/null | awk '/Name :/ && ! /loginwindow/ {print $3}')"
    if [ -z "$user" ] || [ "$user" = "root" ] || [ "$user" = "loginwindow" ]; then
        console_user=""
        console_uid=""
        return 1
    fi
    uid="$(id -u "$user" 2>/dev/null)"
    if [ -z "$uid" ]; then
        console_user=""
        console_uid=""
        return 1
    fi
    console_user="$user"
    console_uid="$uid"
    return 0
}

# wait_for_console_user SECONDS - waits for a logged-in user whose Dock is running (Setup Assistant done).
wait_for_console_user() {
    local deadline
    deadline=$(( $(now_epoch) + $1 ))
    while :; do
        if detect_console_user && pgrep -x -u "$console_uid" Dock >/dev/null 2>&1; then
            log "Console user: $console_user (uid $console_uid)."
            return 0
        fi
        if [ "$(now_epoch)" -ge "$deadline" ]; then
            log "No console user after ${1}s."
            console_user=""
            console_uid=""
            return 1
        fi
        sleep 5
    done
}

# run_as_user COMMAND [ARGS...] - runs in the console user's session.
run_as_user() {
    launchctl asuser "$console_uid" sudo -u "$console_user" "$@"
}

user_full_name() {
    local name
    name="$(id -F "$console_user" 2>/dev/null)"
    printf '%s' "${name:-$console_user}"
}

# wallpaper_fingerprint FILE - SHA-256 of the file, empty when it cannot be read.
wallpaper_fingerprint() {
    shasum -a 256 "$1" 2>/dev/null | awk '{print $1}'
}

# apply_wallpaper - sets the bundled desktop wallpaper for the console user. Never fatal.
# The wallpaper is applied once per image: its SHA-256 is stored in the state directory after a successful
# change, so a wallpaper the user picks afterwards is never replaced on later runs. Shipping a different
# image in a later bundle version applies that image once. Needs a console user; otherwise it is skipped
# and tried again on the next run.
apply_wallpaper() {
    local source target marker fingerprint
    [ -n "${wallpaper_source:-}" ] || return 0
    source="$script_dir/$wallpaper_source"
    target="${wallpaper_target:-}"
    marker="$state_dir/wallpaper.applied"
    if [ -z "$target" ] || [ ! -f "$source" ]; then
        log_warn "Wallpaper file is missing from the bundle ($source); skipping."
        return 0
    fi
    fingerprint="$(wallpaper_fingerprint "$source")"
    if [ -z "$fingerprint" ]; then
        log_warn "Could not read the wallpaper file; skipping."
        return 0
    fi
    # The scaling mode is part of the fingerprint, so a Mac that got the image with another mode gets it again.
    fingerprint="$fingerprint:fill"
    if [ "$(state_read wallpaper.applied)" = "$fingerprint" ]; then
        log "Wallpaper already applied; leaving the current wallpaper alone."
        return 0
    fi
    if [ -z "$console_user" ] || [ -z "$console_uid" ]; then
        log "No console user yet; the wallpaper will be applied on a later run."
        return 0
    fi
    # A copy outside the framework keeps the wallpaper working after uninstall.sh removes the framework.
    if ! mkdir -p "$(dirname "$target")" || ! cp -f "$source" "$target"; then
        log_warn "Could not copy the wallpaper to $target; skipping."
        return 0
    fi
    chown root:wheel "$target" 2>/dev/null
    chmod 644 "$target"
    log "Applying wallpaper $target for $console_user."
