                    url="$(grep -o 'href="/swiftDialog/swiftDialog/releases/download/[^"]*\.pkg"' "$tmp/assets.html" | head -n 1 | sed 's/^href="/https:\/\/github.com/; s/"$//')"
                fi
                ;;
        esac
    fi
    printf '%s' "$url"
}

# dialog_install_once - downloads the latest official swiftDialog release package, verifies that it is signed
# by a trusted Developer ID of the swiftDialog developer team and installs it. Returns non-zero on any failure.
dialog_install_once() {
    local team="${dialog_team_id:-PWA5E9TQ59}"
    local tmp url pkg signature rc=1
    tmp="$(mktemp -d /private/tmp/dialog-install.XXXXXX)" || { log_error "Cannot create a temporary folder for swiftDialog."; return 1; }
    pkg="$tmp/dialog.pkg"
    url="$(dialog_release_url "$tmp")"
    case "$url" in
        https://github.com/swiftDialog/swiftDialog/releases/download/*)
            log "Downloading swiftDialog from $url"
            if ! curl -fsSL --connect-timeout 15 --max-time 600 "$url" -o "$pkg" >> "$logfile" 2>&1; then
                log_warn "swiftDialog download failed."
            else
                signature="$(pkgutil --check-signature "$pkg" 2>&1)"
                # The status line proves macOS trusts the certificate chain; the team ID proves who signed it.
                if printf '%s' "$signature" | grep -q "Status: signed by a developer certificate issued by Apple" \
                    && printf '%s' "$signature" | grep -q "($team)"; then
                    log "swiftDialog package signature verified (trusted Developer ID, team $team)."
                    if installer -pkg "$pkg" -target / >> "$logfile" 2>&1; then
                        rc=0
                    else
                        log_warn "installer failed for the swiftDialog package."
                    fi
                else
                    log_error "swiftDialog package is not signed by a trusted Developer ID of team $team; not installing."
                fi
            fi
            ;;
        *)
            log_warn "No swiftDialog package found in the release information."
            ;;
    esac
    rm -rf "$tmp"
    return $rc
}

# dialog_ensure_installed - installs or updates swiftDialog when it is missing or older than dialog_min_version.
# Up to three attempts. Never fatal: without swiftDialog the run continues without a dialog.
dialog_ensure_installed() {
    local attempt=1
    if dialog_installed_ok; then
        log "swiftDialog is present and meets the minimum version $dialog_min_version."
        return 0
    fi
    if [ -x "$dialog_path" ]; then
        log "swiftDialog is older than $dialog_min_version; updating it."
    else
        log "swiftDialog is not installed at $dialog_path; installing it."
    fi
    while [ "$attempt" -le 3 ]; do
        wait_for_network 120 || true
        if dialog_install_once && dialog_installed_ok; then
            log "swiftDialog installed: $("$dialog_path" --version 2>/dev/null | head -n 1)"
            return 0
        fi
        log_warn "swiftDialog installation attempt $attempt of 3 did not succeed."
        attempt=$((attempt + 1))
        [ "$attempt" -le 3 ] && sleep 20
    done
    log_error "swiftDialog could not be installed automatically; continuing without a dialog unless Intune installs it."
    return 1
}

# dialog_prepare - preconditions: binary present (waits while Intune installs it), version, console user.
dialog_prepare() {
    local deadline version
    if [ -z "$console_user" ]; then
        log "No console user: the dialog is skipped and non-disruptive tasks continue."
        return 1
    fi
    deadline=$(( $(now_epoch) + ${dialog_wait_timeout:-600} ))
    while [ ! -x "$dialog_path" ]; do
        if [ "$(now_epoch)" -ge "$deadline" ]; then
            log_error "swiftDialog not found at $dialog_path; continuing without a dialog."
            return 1
        fi
        sleep 10
    done
    version="$("$dialog_path" --version 2>/dev/null | head -n 1)"
    if [ -z "$version" ] || ! version_ge "$version" "$dialog_min_version"; then
        log_error "swiftDialog ${version:-unknown} is older than the required $dialog_min_version; continuing without a dialog."
        return 1
    fi
    log "swiftDialog $version found at $dialog_path."
    return 0
}

# dialog_check_images JSON - logs every bundled image the dialog uses and warns about missing ones.
dialog_check_images() {
    local reference name
    printf '%s' "$1" | grep -o '__INSTALL_DIR__/icons/[^"]*' | sort -u | while IFS= read -r reference; do
        name="${reference#__INSTALL_DIR__/icons/}"
        if [ -f "$script_dir/icons/$name" ]; then
            log "Dialog image: $script_dir/icons/$name"
        else
            log_warn "Dialog image missing: $script_dir/icons/$name"
        fi
    done
}

# dialog_start - writes the resolved configuration and launches swiftDialog in the user's session.
dialog_start() {
    local json
    dialog_jsonfile="$(mktemp /var/tmp/enrollment-dialog.XXXXXX)" || return 1
    register_temp "$dialog_jsonfile"
    dialog_commandfile="$(mktemp /var/tmp/enrollment-commands.XXXXXX)" || return 1
    register_temp "$dialog_commandfile"
    json="$(cat "$script_dir/config/dialog.json")"
    # Image paths are written as __INSTALL_DIR__/icons/... and resolved to where this copy actually runs,
    # so the logo and banner appear even when the framework is not at the configured install location.
    dialog_check_images "$json"
    json="$(replace_all "$json" "__INSTALL_DIR__" "$(json_escape "$script_dir")")"
    apply_placeholders "$json" json > "$dialog_jsonfile"
    chmod 644 "$dialog_jsonfile" "$dialog_commandfile"

    set -- --jsonfile "$dialog_jsonfile" --commandfile "$dialog_commandfile"
    if is_true "$lock_button"; then
        set -- "$@" --button1disabled
        dialog_unlocked=0
    else
        dialog_unlocked=1
    fi
    run_as_user "$dialog_path" "$@" >> "$logfile" 2>&1 &
    dialog_pid=$!
    dialog_active=1
    log "swiftDialog started (PID $dialog_pid)."
    sleep 2
    return 0
}

# dialog_cmd LINE - appends one command to the command file.
dialog_cmd() {
    if ! is_true "$dialog_active"; then
        return 0
    fi
    printf '%s\n' "$1" >> "$dialog_commandfile"
    log_debug "dialog: $1"
    sleep 0.1
}

# dialog_status_for STATUS - maps a task status to a swiftDialog list status.
dialog_status_for() {
    case "$1" in
        waiting | running) printf 'wait' ;;
        complete) printf 'success' ;;
        completeWithWarnings) printf 'error' ;;
        failed | timedOut) printf 'fail' ;;
        *) printf 'pending' ;;
    esac
}

# dialog_set_item INDEX STATUS TEXT
dialog_set_item() {
    case "$1" in
        '' | -*) return 0 ;;
    esac
    dialog_cmd "listitem: index: $1, status: $(dialog_status_for "$2"), statustext: $(one_line "$3")"
}

# dialog_progress DONE TEXT
dialog_progress() {
    dialog_cmd "progress: $1"
    dialog_cmd "progresstext: $(one_line "$2")"
}

# dialog_message TEXT - placeholders resolved, newlines sent as \n.
dialog_message() {
    local message
    message="$(apply_placeholders "$1" plain)"
    message="$(replace_all "$message" "$newline" '\n')"
    dialog_cmd "message: $message"
}

dialog_unlock() {
    if is_true "$dialog_unlocked"; then
        return 0
    fi
    dialog_cmd "button1text: $(one_line "$button_text")"
    dialog_cmd "button1: enable"
    dialog_unlocked=1
    log "Completion button unlocked."
}

# dialog_finish OUTCOME - final message, icon and button.
dialog_finish() {
    case "$1" in
        success)
            dialog_message "$msg_completion"
            dialog_cmd "icon: $completion_icon"
            ;;
        warnings)
            dialog_message "$msg_warning"
            dialog_cmd "icon: $completion_icon"
            ;;
        failed)
            dialog_message "$msg_failure"
            ;;
        *)
            dialog_message "$msg_welcome"
            ;;
    esac
    dialog_progress "$total_tasks" "$(outcome_progress_text "$1")"
    # The run is over, so the user can always close the window; the message explains the result.
    dialog_unlock
}

outcome_progress_text() {
    case "$1" in
        success) printf 'Setup complete' ;;
        warnings) printf 'Setup complete with warnings' ;;
        failed) printf 'Setup needs attention' ;;
        *) printf 'Setup will continue later' ;;
    esac
}

# dialog_wait_for_exit SECONDS - waits for the user to close the window, then closes it if needed.
dialog_wait_for_exit() {
    local waited=0
    if ! is_true "$dialog_active" || [ -z "$dialog_pid" ]; then
        return 0
    fi
    dialog_closed_by_user=1
    while kill -0 "$dialog_pid" 2>/dev/null; do
        if [ "$waited" -ge "$1" ]; then
            log "Closing the dialog after ${1}s."
            dialog_closed_by_user=0
            dialog_cmd "quit:"
            sleep 2
            break
        fi
        sleep 2
        waited=$((waited + 2))
    done
    dialog_active=0
}

# dialog_run_completion_command OUTCOME - runs the administrator's command after the user clicked the
# completion button. Skipped when the dialog was closed by timeout, when nothing is configured, on a
# failed run, and in dry-run mode. The command text is not written to the log.
dialog_run_completion_command() {
    local rc
    [ -n "$completion_command" ] || return 0
    case "$1" in
        success | warnings) ;;
        *) return 0 ;;
    esac
    if ! is_true "$dialog_closed_by_user"; then
        log "Completion command skipped: the dialog was not closed by the user."
        return 0
    fi
    if is_true "${dry_run:-0}"; then
        log "Dry run: completion command not executed."
        return 0
    fi
    if is_true "$completion_command_as_user"; then
        if [ -z "$console_user" ] || [ "$console_user" = "root" ] || [ "$console_user" = "loginwindow" ]; then
            log_warn "Completion command skipped: no console user."
            return 0
        fi
        log "Running completion command as $console_user."
        run_with_timeout 60 run_as_user /bin/bash -c "$completion_command" >> "$logfile" 2>&1
    else
        log "Running completion command as root."
        run_with_timeout 60 /bin/bash -c "$completion_command" >> "$logfile" 2>&1
    fi
    rc=$?
    if [ "$rc" -eq 0 ]; then
        log "Completion command finished."
    else
        log_warn "Completion command exited with code $rc."
    fi
    return 0
}

# dialog_quit - asks swiftDialog to close, then makes sure it is gone.
dialog_quit() {
    local waited=0
    if ! is_true "$dialog_active"; then
        return 0
    fi
    dialog_cmd "quit:"
    while [ -n "$dialog_pid" ] && kill -0 "$dialog_pid" 2>/dev/null && [ "$waited" -lt 5 ]; do
        sleep 1
        waited=$((waited + 1))
    done
    if [ -n "$dialog_pid" ] && kill -0 "$dialog_pid" 2>/dev/null; then
        log_warn "swiftDialog did not quit; stopping it."
        terminate_pid_tree "$dialog_pid"
    fi
    dialog_active=0
}
"""#

    static let libraryValidation = #"""
# shellcheck shell=bash
# validation.sh - detection and validation checks for tasks. Reads the TASK_* variables of the loaded task.
# Generated by Enrollment Bundle Studio. Sourced by enrollment.sh. Bash 3.2 compatible.

# run_check_command COMMAND - runs an administrator-defined check as root; output goes to the log.
run_check_command() {
    /bin/bash -c "$1" >> "$logfile" 2>&1
}

bundle_identifier_of() {
    /usr/libexec/PlistBuddy -c "Print :CFBundleIdentifier" "$1/Contents/Info.plist" 2>/dev/null
}

# detect_application - true when the loaded application task's detection rule is satisfied.
detect_application() {
    case "$TASK_DETECTION" in
        applicationPath)
            [ -d "$TASK_APP_PATH" ]
            ;;
        bundleIdentifier)
            [ -d "$TASK_APP_PATH" ] && [ "$(bundle_identifier_of "$TASK_APP_PATH")" = "$TASK_BUNDLE_ID" ]
            ;;
        packageReceipt)
            pkgutil --pkg-info "$TASK_DETECTION_VALUE" >/dev/null 2>&1
            ;;
        processRunning)
            pgrep -x "$TASK_PROCESS_NAME" >/dev/null 2>&1
            ;;
        customCommand)
            run_check_command "$TASK_DETECTION_VALUE"
            ;;
        *)
            log_error "Task $TASK_ID has unknown detection method '$TASK_DETECTION'"
            return 1
            ;;
    esac
}

# wait_until SECONDS CHECK_FUNCTION - polls until the check succeeds or the time runs out.
wait_until() {
    local deadline check="$2"
    deadline=$(( $(now_epoch) + $1 ))
    while :; do
        if "$check"; then
            return 0
        fi
        if [ "$(now_epoch)" -ge "$deadline" ]; then
            return 1
        fi
        sleep "${detection_interval:-10}"
    done
}

_validation_command_check() {
    run_check_command "$TASK_VALIDATION_VALUE"
}

intune_agent_present() {
    [ -d "/Library/Intune/Microsoft Intune Agent.app" ]
}

# verify_sha256 PATH EXPECTED
verify_sha256() {
    local actual
    actual="$(shasum -a 256 "$1" 2>/dev/null | awk '{print $1}')"
    [ -n "$actual" ] && [ "$actual" = "$2" ]
}
"""#

    static let libraryTaskRunner = #"""
# shellcheck shell=bash
# task-runner.sh - loads data-only task files, runs them with timeouts, retries, dependencies and
# controlled parallelism, and keeps the dialog in step. Task files never contain code.
# Generated by Enrollment Bundle Studio. Sourced by enrollment.sh. Bash 3.2 compatible.

running_entries=""
total_tasks=0
finished_tasks=0
enrollment_deadline=0

task_reset() {
    TASK_ID=""
    TASK_NAME=""
    TASK_TYPE=""
    TASK_STRATEGY=""
    TASK_REQUIRED=0
    TASK_VISIBLE=1
    TASK_LIST_INDEX=-1
    TASK_LIST_SUMMARY=0
    TASK_CONTEXT="root"
    TASK_TIMEOUT=900
    TASK_RETRIES=0
    TASK_DEPENDS=""
    TASK_BATCH=0
    TASK_PARALLEL_GROUP=""
    TASK_ALLOW_SKIP=0
    TASK_ALLOW_RERUN=0
    TASK_SUCCESS_CODES="0"
    TASK_MSG_WAITING=""
    TASK_MSG_PROGRESS=""
    TASK_MSG_SUCCESS=""
    TASK_MSG_WARNING=""
    TASK_MSG_FAILURE=""
    TASK_APP_PATH=""
    TASK_BUNDLE_ID=""
    TASK_PROCESS_NAME=""
    TASK_DETECTION=""
    TASK_DETECTION_VALUE=""
    TASK_VALIDATION_VALUE=""
    TASK_INSTALLER=""
    TASK_INSTALLER_SHA256=""
    TASK_SCRIPT=""
}

# task_load FILE - resets and loads one task file after checking it is root-protected (when running as root).
task_load() {
    task_reset
    if [ "$(id -u)" -eq 0 ] && ! file_is_root_protected "$1"; then
        log_error "Task file $1 is not owned by root or is writable by others; refusing to load it."
        return 1
    fi
    # shellcheck source=/dev/null
    . "$1"
    case "$TASK_ID" in
        '' | *[!a-z0-9.-]*)
            log_error "Task file $1 has an invalid TASK_ID '$TASK_ID'."
            return 1
            ;;
    esac
    return 0
}

task_files() {
    find "$script_dir/tasks" -maxdepth 1 -type f -name '*.sh' 2>/dev/null | sort
}

count_lines() {
    local count=0 line
    while IFS= read -r line; do
        if [ -n "$line" ]; then
            count=$((count + 1))
        fi
    done <<< "$1"
    printf '%s' "$count"
}

# task_text STATUS - the loaded task's message for a status.
task_text() {
    case "$1" in
        waiting | pending) printf '%s' "$TASK_MSG_WAITING" ;;
        running)
            if [ "$TASK_TYPE" = "applicationDetection" ]; then
                printf '%s' "$TASK_MSG_WAITING"
            else
                printf '%s' "$TASK_MSG_PROGRESS"
            fi
            ;;
        complete) printf '%s' "$TASK_MSG_SUCCESS" ;;
        completeWithWarnings) printf '%s' "$TASK_MSG_WARNING" ;;
        skipped) printf 'Skipped' ;;
        timedOut) printf 'Timed out' ;;
        *) printf '%s' "$TASK_MSG_FAILURE" ;;
    esac
}

task_set() {
    state_set_task "$TASK_ID" "$1" "${2:-$(task_text "$1")}"
}

# ---------------------------------------------------------------------------
# Execution of one task. Runs in a background subshell; the result is the state file.
# ---------------------------------------------------------------------------

execute_task() {
    local dependency dependency_status
    for dependency in $TASK_DEPENDS; do
        dependency_status="$(state_get_task "$dependency")"
        if ! state_is_acceptable "$dependency_status"; then
            if [ "$TASK_TYPE" = "finalValidation" ]; then
                task_set failed
            else
                task_set skipped "Skipped: $dependency did not complete"
            fi
            return 0
        fi
    done
    if [ "$TASK_CONTEXT" = "user" ] && [ -z "$console_user" ]; then
        task_set pending "Waiting for a logged-in user"
        return 0
    fi
    case "$TASK_TYPE" in
        applicationDetection) run_detection_task ;;
        packageInstallation) run_installer_task ;;
        shellScript) run_script_task ;;
        intuneSync) run_intune_sync_task ;;
        waitCondition) run_wait_task ;;
        configurationValidation) run_validation_task ;;
        finalValidation) task_set complete ;;
        *) task_set failed "Unknown task type $TASK_TYPE" ;;
    esac
}

run_detection_task() {
    if [ "$TASK_STRATEGY" = "customScript" ] && [ -n "$TASK_SCRIPT" ]; then
        run_app_script_task
        return 0
    fi
    if [ "$TASK_STRATEGY" = "detectionOnly" ]; then
        if detect_application; then
            task_set complete
        else
            task_set failed
        fi
        return 0
    fi
    log "Waiting up to ${TASK_TIMEOUT}s for $TASK_NAME ($TASK_DETECTION)."
    if wait_until "$TASK_TIMEOUT" detect_application; then
        task_set complete
    else
        task_set timedOut
    fi
}

run_installer_task() {
    local package attempt=1 attempts rc result=failed
    if detect_application; then
        task_set complete "Already installed"
        return 0
    fi
    package="$script_dir/$TASK_INSTALLER"
    if [ -z "$TASK_INSTALLER" ] || [ ! -f "$package" ]; then
        log_error "Installer package for $TASK_ID is missing: $package"
        task_set failed "Installer package missing"
        return 0
    fi
    if [ -n "$TASK_INSTALLER_SHA256" ] && ! verify_sha256 "$package" "$TASK_INSTALLER_SHA256"; then
        log_error "Installer package for $TASK_ID failed its SHA-256 check."
        task_set failed "Installer failed its integrity check"
        return 0
    fi
    attempts=$((TASK_RETRIES + 1))
    while [ "$attempt" -le "$attempts" ]; do
        log "Installing $TASK_NAME from $TASK_INSTALLER (attempt $attempt of $attempts)."
        run_with_timeout "$TASK_TIMEOUT" installer -pkg "$package" -target / >> "$logfile" 2>&1
        rc=$?
        if [ "$rc" -eq 0 ] && detect_application; then
            task_set complete
            return 0
        fi
        if [ "$rc" -eq 124 ]; then
            result=timedOut
        else
            result=failed
            log "installer exited with $rc for $TASK_ID."
        fi
        attempt=$((attempt + 1))
    done
    task_set "$result"
}

# run_app_script_task - "Run custom script" applications: skip the script when the app is already detected,
# otherwise run the linked script (with timeout and retries), then detect the app.
run_app_script_task() {
    local script attempt=1 attempts rc result=failed
    if detect_application; then
        task_set complete "Already installed"
        return 0
    fi
    script="$script_dir/$TASK_SCRIPT"
    if [ ! -f "$script" ]; then
        log_error "Script for $TASK_ID is missing: $script"
        task_set failed "Script file missing"
        return 0
    fi
    attempts=$((TASK_RETRIES + 1))
    while [ "$attempt" -le "$attempts" ]; do
        log "Running $TASK_SCRIPT for $TASK_NAME as $TASK_CONTEXT (attempt $attempt of $attempts)."
        if [ "$TASK_CONTEXT" = "user" ]; then
            run_with_timeout "$TASK_TIMEOUT" run_as_user "$script" >> "$logfile" 2>&1
        else
            run_with_timeout "$TASK_TIMEOUT" "$script" >> "$logfile" 2>&1
        fi
        rc=$?
        if code_in_list "$rc" "$TASK_SUCCESS_CODES"; then
            if detect_application; then
                task_set complete
                return 0
            fi
            log "$TASK_SCRIPT succeeded but $TASK_NAME is not detected yet; waiting for it."
            if wait_until "$TASK_TIMEOUT" detect_application; then
                task_set complete
            else
                task_set timedOut
            fi
            return 0
        fi
        if [ "$rc" -eq 124 ]; then
            result=timedOut
        else
            result=failed
        fi
        log "$TASK_SCRIPT exited with $rc (success codes: $TASK_SUCCESS_CODES)."
        attempt=$((attempt + 1))
    done
    task_set "$result"
}

run_script_task() {
    local script attempt=1 attempts rc result=failed
    script="$script_dir/$TASK_SCRIPT"
    if [ -z "$TASK_SCRIPT" ] || [ ! -f "$script" ]; then
        log_error "Script for $TASK_ID is missing: $script"
        task_set failed "Script file missing"
        return 0
    fi
    attempts=$((TASK_RETRIES + 1))
    while [ "$attempt" -le "$attempts" ]; do
        log "Running $TASK_SCRIPT as $TASK_CONTEXT (attempt $attempt of $attempts)."
        if [ "$TASK_CONTEXT" = "user" ]; then
            run_with_timeout "$TASK_TIMEOUT" run_as_user "$script" >> "$logfile" 2>&1
        else
            run_with_timeout "$TASK_TIMEOUT" "$script" >> "$logfile" 2>&1
        fi
        rc=$?
        if code_in_list "$rc" "$TASK_SUCCESS_CODES"; then
            task_set complete
            return 0
        fi
        if [ "$rc" -eq 124 ]; then
            result=timedOut
        else
            result=failed
        fi
        log "$TASK_SCRIPT exited with $rc (success codes: $TASK_SUCCESS_CODES)."
        attempt=$((attempt + 1))
    done
    task_set "$result"
}

run_intune_sync_task() {
    local rc
    if ! wait_until "$TASK_TIMEOUT" intune_agent_present; then
        task_set timedOut "Intune agent not found"
        return 0
    fi
    if [ -n "$TASK_VALIDATION_VALUE" ]; then
        run_with_timeout "$TASK_TIMEOUT" run_check_command "$TASK_VALIDATION_VALUE"
        rc=$?
        if [ "$rc" -ne 0 ]; then
            task_set completeWithWarnings "Sync command exited with $rc"
            return 0
        fi
    fi
    task_set complete
}

run_wait_task() {
    log "Waiting up to ${TASK_TIMEOUT}s for condition of $TASK_ID."
    if wait_until "$TASK_TIMEOUT" _validation_command_check; then
        task_set complete
    else
        task_set timedOut
    fi
}

run_validation_task() {
    local attempt=1 attempts rc
    attempts=$((TASK_RETRIES + 1))
    while [ "$attempt" -le "$attempts" ]; do
        run_with_timeout "$TASK_TIMEOUT" run_check_command "$TASK_VALIDATION_VALUE"
        rc=$?
        if [ "$rc" -eq 0 ]; then
            task_set complete
            return 0
        fi
        log "Validation for $TASK_ID exited with $rc (attempt $attempt of $attempts)."
        attempt=$((attempt + 1))
        sleep 5
    done
    task_set failed
}

# ---------------------------------------------------------------------------
# Scheduling and dialog updates. Runs in the main shell.
# ---------------------------------------------------------------------------

# aggregate_statuses "s1 s2 ..." - one status for a summary row (same rules as the app's preview).
aggregate_statuses() {
    local statuses=" $1 " started=0 status
    case "$statuses" in *" failed "*) printf 'failed'; return 0 ;; esac
    case "$statuses" in *" timedOut "*) printf 'timedOut'; return 0 ;; esac
    case "$statuses" in *" running "*) printf 'running'; return 0 ;; esac
    for status in $1; do
        if state_is_terminal "$status"; then
            started=1
        fi
    done
    case "$statuses" in
        *" pending "* | *" waiting "*)
            if [ "$started" -eq 1 ]; then
                printf 'running'
            else
                printf 'pending'
            fi
            return 0
            ;;
    esac
    case "$statuses" in *" completeWithWarnings "*) printf 'completeWithWarnings'; return 0 ;; esac
    for status in $1; do
        if [ "$status" != "skipped" ]; then
            printf 'complete'
            return 0
        fi
    done
    printf 'skipped'
}

# update_dialog_for_task STATUS - for the loaded task.
update_dialog_for_task() {
    local status="$1" text index="$TASK_LIST_INDEX"
    if [ "$index" -lt 0 ] 2>/dev/null; then
        return 0
    fi
    if is_true "$TASK_LIST_SUMMARY"; then
        update_summary_item "$index"
        return 0
    fi
    text="$(state_get_task_message "$TASK_ID")"
    if [ -z "$text" ] || ! state_is_terminal "$status"; then
        text="$(task_text "$status")"
    fi
    dialog_set_item "$index" "$status" "$text"
}

# update_summary_item INDEX - aggregates every task shown in one summary row.
update_summary_item() {
    local index="$1" result
    result="$(
        statuses=""
        members=0
        finished=0
        while IFS= read -r file; do
            [ -n "$file" ] || continue
            task_load "$file" >/dev/null 2>&1 || continue
            if [ "$TASK_LIST_INDEX" = "$index" ]; then
                status="$(state_get_task "$TASK_ID")"
                statuses="$statuses $status"
                members=$((members + 1))
                if state_is_terminal "$status"; then
                    finished=$((finished + 1))
                fi
            fi
        done <<< "$(task_files)"
        printf '%s|%s of %s finished' "$(aggregate_statuses "$statuses")" "$finished" "$members"
    )"
    dialog_set_item "$index" "${result%%|*}" "${result#*|}"
}

update_progress() {
    dialog_progress "$finished_tasks" "$finished_tasks of $total_tasks complete"
}

# required_tasks_acceptable - every required task is complete, complete with warnings, or skipped where allowed.
required_tasks_acceptable() {
    (
        while IFS= read -r file; do
            [ -n "$file" ] || continue
            task_load "$file" >/dev/null 2>&1 || exit 1
            if is_true "$TASK_REQUIRED"; then
                status="$(state_get_task "$TASK_ID")"
                if state_is_acceptable "$status"; then
                    continue
                fi
                if [ "$status" = "skipped" ] && is_true "$TASK_ALLOW_SKIP"; then
                    continue
                fi
                exit 1
            fi
        done <<< "$(task_files)"
        exit 0
    )
}

check_unlock() {
    if is_true "$lock_button" && ! is_true "$dialog_unlocked" && required_tasks_acceptable; then
        dialog_unlock
    fi
}

running_count() {
    count_lines "$running_entries"
}

terminate_pid_tree() {
    local family
    family="$(descendant_pids "$1")"
    # shellcheck disable=SC2086
    signal_pids TERM $family "$1"
}

# poll_running - collects finished background tasks and enforces the maximum enrollment duration.
poll_running() {
    local remaining="" entry pid file status
    while IFS= read -r entry; do
        [ -n "$entry" ] || continue
        pid="${entry%%|*}"
        file="${entry#*|}"
        if kill -0 "$pid" 2>/dev/null; then
            if [ "$(now_epoch)" -lt "$enrollment_deadline" ]; then
                remaining="$remaining$entry$newline"
                continue
            fi
            log_warn "Maximum enrollment duration reached; stopping PID $pid."
            terminate_pid_tree "$pid"
            sleep 1
            wait "$pid" 2>/dev/null
            if task_load "$file"; then
                task_set timedOut "Stopped at the maximum enrollment duration"
            fi
        else
            wait "$pid" 2>/dev/null
        fi
        task_load "$file" || continue
        status="$(state_get_task "$TASK_ID")"
        if [ "$status" = "running" ]; then
            task_set failed "Task ended unexpectedly"
            status="failed"
        fi
        finished_tasks=$((finished_tasks + 1))
        update_dialog_for_task "$status"
        update_progress
        check_unlock
    done <<< "$running_entries"
    running_entries="$remaining"
}

# run_batch FILES - tasks of one batch run concurrently (at most max_parallel); batches run in order.
run_batch() {
    local file status
    while IFS= read -r file; do
        [ -n "$file" ] || continue
        task_load "$file" || continue
        status="$(state_get_task "$TASK_ID")"
        if state_is_acceptable "$status" && ! is_true "$TASK_ALLOW_RERUN"; then
            log "Task $TASK_ID is already $status; not running it again."
            finished_tasks=$((finished_tasks + 1))
            update_dialog_for_task "$status"
            update_progress
            check_unlock
            continue
        fi
        if [ "$(now_epoch)" -ge "$enrollment_deadline" ]; then
            task_set timedOut "Not started: maximum enrollment duration reached"
            finished_tasks=$((finished_tasks + 1))
            update_dialog_for_task timedOut
            continue
        fi
        while [ "$(running_count)" -ge "${max_parallel:-4}" ]; do
            poll_running
            sleep 1
        done
        task_load "$file" || continue
        task_set running
        update_dialog_for_task running
        ( task_load "$file" && execute_task ) < /dev/null &
        running_entries="$running_entries$!|$file$newline"
        log "Started $TASK_ID (PID $!)."
    done <<< "$1"
    while [ -n "$running_entries" ]; do
        poll_running
        if [ -n "$running_entries" ]; then
            sleep 1
        fi
    done
}

# run_all_tasks - runs every task file in order, batch by batch.
run_all_tasks() {
    local files file batch current="" batch_files=""
    files="$(task_files)"
    total_tasks="$(count_lines "$files")"
    finished_tasks=0
    enrollment_deadline=$(( $(now_epoch) + max_duration ))
    log "Running $total_tasks task(s); maximum duration ${max_duration}s."
    while IFS= read -r file; do
        [ -n "$file" ] || continue
        if ! task_load "$file"; then
            continue
        fi
        batch="$TASK_BATCH"
        if [ -n "$batch_files" ] && [ "$batch" != "$current" ]; then
            run_batch "$batch_files"
            batch_files=""
        fi
        current="$batch"
        batch_files="$batch_files$file$newline"
    done <<< "$files"
    if [ -n "$batch_files" ]; then
        run_batch "$batch_files"
    fi
}

# stop_running_tasks - used by the signal handler.
stop_running_tasks() {
    local entry pid
    while IFS= read -r entry; do
        [ -n "$entry" ] || continue
        pid="${entry%%|*}"
        terminate_pid_tree "$pid"
    done <<< "$running_entries"
    running_entries=""
}

# evaluate_outcome - prints success, warnings, failed or deferred.
evaluate_outcome() {
    (
        outcome="success"
        deferred=0
        warnings=0
        while IFS= read -r file; do
            [ -n "$file" ] || continue
            task_load "$file" >/dev/null 2>&1 || continue
            status="$(state_get_task "$TASK_ID")"
            if is_true "$TASK_REQUIRED"; then
                case "$status" in
                    failed | timedOut) printf 'failed'; exit 0 ;;
                    skipped)
                        if ! is_true "$TASK_ALLOW_SKIP"; then
                            printf 'failed'
                            exit 0
                        fi
                        ;;
                esac
            fi
            case "$status" in
                complete) ;;
                completeWithWarnings) warnings=1 ;;
                failed | timedOut | skipped) warnings=1 ;;
                *) deferred=1 ;;
            esac
        done <<< "$(task_files)"
        if [ "$deferred" -eq 1 ]; then
            outcome="deferred"
        elif [ "$warnings" -eq 1 ]; then
            outcome="warnings"
        fi
        printf '%s' "$outcome"
    )
}
